Microsegmentación.ejemplo:
# Regla conceptual de microsegmentación: solo el servicio 'checkout' accede a 'postgres' en 5432
from: { label: "app=checkout" }
to:   { label: "app=postgres" }
allow: [{ protocol: "TCP", port: 5432 }]

Proxy inverso.ejemplo:
# Bloque básico de proxy inverso en Nginx con terminación TLS y cabeceras reales
server {
  listen 443 ssl http2;
  location /api/ {
    proxy_pass http://backend_pool;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
  }
}
